+it.each(['low', 'high'] as const)('restricts the list to priority %s and keeps newest-first order', async (priority) => {
+  const { database, repository } = setup();
+  const findMany = vi.spyOn(database.todo, 'findMany').mockResolvedValue([record]);
+  expect(await repository.list({ priority })).toEqual([todo]);
+  expect(findMany).toHaveBeenCalledTimes(1);
+  expect(findMany).toHaveBeenCalledWith({
+    where: { priority },
+    orderBy: [{ created_at: 'desc' }, { id: 'desc' }],
+  });
+});
+it('does not add a where clause for an empty list query', async () => {
+  const { database, repository } = setup();
+  const findMany = vi.spyOn(database.todo, 'findMany').mockResolvedValue([]);
+  expect(await repository.list({})).toEqual([]);
+  expect(findMany.mock.calls[0][0]).not.toHaveProperty('where');
+});
